        static Health SpawnTraining(CharacterInstance actor,Vector3 at){var world=ROM.Horde.Horde.Instance;var alive=(System.Collections.IDictionary)typeof(ROM.Horde.Horde).GetField("_aliveEnemies",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(world);var before=alive.Keys.Cast<Health>().ToArray();var marker=new GameObject("Progression probe enemy spawn");marker.transform.position=at;var method=typeof(ROM.Horde.Horde).GetMethod("SpawnEnemy",BindingFlags.NonPublic|BindingFlags.Instance);var kind=Enum.Parse(method.GetParameters()[0].ParameterType,"Melee");if(!(bool)method.Invoke(world,new object[]{kind,marker.transform}))throw new Exception("Fixture enemy spawn failed");UnityEngine.Object.Destroy(marker);var health=alive.Keys.Cast<Health>().First(h=>!before.Contains(h));alive.Remove(health);health.ServerMakeTrainingTarget();var bot=health.GetComponent<BotAI>();if(bot)bot.Passive=true;return health;}
        static Vector2 Center(Transform t)=>RectTransformUtility.WorldToScreenPoint(null,((RectTransform)t).TransformPoint(((RectTransform)t).rect.center));
        static int KillEncounterEnemies(CharacterInstance actor){var enemies=(System.Collections.IDictionary)typeof(ROM.Horde.Horde).GetField("_encounterByEnemy",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(ROM.Horde.Horde.Instance);int count=0;foreach(var health in enemies.Keys.Cast<Health>().ToArray())if(health&&health.CurrentHealth>0&&Vector3.Distance(health.transform.position,actor.transform.position)<180){health.Server_ChangeHealthStateRaw(999999,0,AttackType.explosion,actor.Health,0);if(health.CurrentHealth<=0)count++;}return count;}
        static void Capture(string name)=>typeof(RiftGameplayHUDProbe).GetMethod("CaptureGame",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{Folder+(SessionState.GetBool(Key+"UI",false)?"/ui-final-":SessionState.GetBool(Key+"Gear",false)?"/gear-":"/progression-")+name+".png",1920,1080});
        static void Finish(bool ok){if(keyboard!=null){InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);keyboard=null;mouse=null;if(originalKeyboard!=null)originalKeyboard.MakeCurrent();if(originalMouse!=null)originalMouse.MakeCurrent();InputSystem.settings.backgroundBehavior=(InputSettings.BackgroundBehavior)SessionState.GetInt(Key+"Background",0);InputSystem.settings.editorInputBehaviorInPlayMode=(InputSettings.EditorInputBehaviorInPlayMode)SessionState.GetInt(Key+"Editor",0);}File.WriteAllLines(Folder+(SessionState.GetBool(Key+"Performance",false)?"/performance-validation.txt":SessionState.GetBool(Key+"Ragdoll",false)?"/ragdoll-validation.txt":SessionState.GetBool(Key+"UI",false)?"/ui-validation.txt":SessionState.GetBool(Key+"Gear",false)?"/gear-validation.txt":"/validation.txt"),report);SessionState.SetInt(Key+"Result",ok?0:1);EditorApplication.update-=Tick;EditorApplication.isPlaying=false;}
